30	interface JobSidebarProps {
31	  showDashboard?: boolean;
32	  showMyJobs?: boolean;
33	  onNewJob?: () => void;
34	  onDashboard?: () => void;
35	  onMyJobs?: () => void;
36	  onAuthRequired?: () => void;
37	  isAuthenticated?: boolean;
38	  selectedJobId?: string | null;
39	}
40	
41	interface NavItem {
42	  icon: React.ComponentType<{ className?: string }>;
43	  label: string;
44	  isActive: boolean;
45	  onClick: (() => void) | undefined;
46	  show?: boolean;
47	}
48	
49	const NavItemRow = ({ icon: Icon, label, isActive, onClick }: NavItem) => (
50	  <SidebarMenuItem>
51	    <SidebarMenuButton
52	      isActive={isActive}
53	      onClick={onClick}
54	      tooltip={label}
55	      className={cn(
56	        "h-8 gap-2.5 rounded-md text-[13px] font-medium transition-colors duration-100",
57	        isActive
58	          ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold"
59	          : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
60	      )}
61	    >
62	      <Icon className={cn("h-4 w-4 shrink-0", isActive ? "text-foreground" : "text-muted-foreground")} />
63	      <span>{label}</span>
64	    </SidebarMenuButton>
65	  </SidebarMenuItem>
66	);
67	
68	const SectionLabel = ({ children }: { children: string }) => (
69	  <p className="px-2 pt-5 pb-1.5 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/50 select-none group-data-[collapsible=icon]:hidden">
70	    {children}
71	  </p>
72	);
73	
74	const JobSidebar = ({
75	  showDashboard,
76	  showMyJobs,
77	  onDashboard,
78	  onMyJobs,
79	  isAuthenticated = true,
80	}: JobSidebarProps) => {
81	  const navigate = useNavigate();
82	  const { pathname } = useLocation();
83	  const { data: config } = usePlatformConfig();
84	  const appName = config?.app_name || "Rankora";
85	  const appLogo = config?.app_logo_url || null;
86	
87	  const mainNav: NavItem[] = [
88	    { icon: Home, label: "Dashboard", isActive: !!showDashboard, onClick: onDashboard, show: isAuthenticated && !!onDashboard },
89	    { icon: Briefcase, label: "My Jobs", isActive: !!showMyJobs, onClick: onMyJobs, show: isAuthenticated && !!onMyJobs },
90	    { icon: Bookmark, label: "Talent Pool", isActive: pathname === "/talent-pool", onClick: () => navigate("/talent-pool"), show: isAuthenticated },
91	    { icon: CheckSquare, label: "Tasks", isActive: pathname === "/tasks", onClick: () => navigate("/tasks"), show: isAuthenticated },
92	    { icon: BarChart3, label: "Reports", isActive: pathname === "/reports", onClick: () => navigate("/reports"), show: isAuthenticated },
93	  ];
94	
95	  const orgNav: NavItem[] = [
96	    { icon: Users, label: "Team Hub", isActive: pathname === "/team", onClick: () => navigate("/team") },
97	    { icon: Building2, label: "Agency Hub", isActive: pathname === "/agency", onClick: () => navigate("/agency") },
98	    { icon: Globe, label: "Career Page", isActive: pathname === "/career-settings", onClick: () => navigate("/career-settings") },
99	    { icon: Plug, label: "Integrations", isActive: pathname === "/integrations", onClick: () => navigate("/integrations") },
100	    { icon: CreditCard, label: "Billing", isActive: pathname === "/billing", onClick: () => navigate("/billing") },
101	    { icon: Settings, label: "Settings", isActive: pathname === "/settings", onClick: () => navigate("/settings") },
102	  ];
103	
104	  return (
105	    <Sidebar collapsible="icon" className="border-r-0">
106	      {/* Brand */}
107	      <SidebarHeader className="!flex-col !gap-0 !p-0 px-2 pt-4 pb-2 group-data-[collapsible=icon]:px-1 group-data-[collapsible=icon]:items-center">
108	        <div className="flex items-center gap-2 px-2">
109	          {appLogo ? (
110	            <img src={appLogo} alt={appName} className="h-5 w-5 shrink-0 object-contain group-data-[collapsible=icon]:h-6 group-data-[collapsible=icon]:w-6" />
111	          ) : (
112	            <Layers className="h-4 w-4 text-primary shrink-0" />
113	          )}
114	          <span className="font-bold text-foreground tracking-tight text-base group-data-[collapsible=icon]:hidden">{appName}</span>
115	        </div>
116	      </SidebarHeader>
117	
118	      {/* Navigation */}
119	      <SidebarContent className="px-2 py-1 group-data-[collapsible=icon]:px-1">
120	        <SectionLabel>Main</SectionLabel>
121	        <SidebarMenu>
122	          {mainNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
123	        </SidebarMenu>
124	
125	        {isAuthenticated && (
126	          <>
127	            <SectionLabel>Organization</SectionLabel>
128	            <SidebarMenu>
129	              {orgNav.map((item) => <NavItemRow key={item.label} {...item} />)}
130	            </SidebarMenu>
131	          </>
132	        )}
133	
134	        <SectionLabel>Support</SectionLabel>
135	        <SidebarMenu>
136	          <SidebarMenuItem>
137	            <Link to="/request-feature" className={cn("flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:px-0", pathname === "/request-feature" ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
138	              <Megaphone className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
139	              <span className="group-data-[collapsible=icon]:hidden">Feature Request</span>
140	            </Link>
141	          </SidebarMenuItem>
142	          <SidebarMenuItem>
143	            <Link to="/changelog" className={cn("flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:px-0", pathname === "/changelog" ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
144	              <FileText className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
145	              <span className="group-data-[collapsible=icon]:hidden">Changelog</span>
146	            </Link>
147	          </SidebarMenuItem>
148	        </SidebarMenu>
149	      </SidebarContent>
150	    </Sidebar>
151	  );
152	};
153	
154	export default JobSidebar;
