37	function getInitials(email?: string | null): string {
38	  if (!email) return "?";
39	  const name = email.split("@")[0];
40	  const parts = name.split(/[._-]/);
41	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
42	  return name[0]?.toUpperCase() || "?";
43	}
44	
45	function getUserName(email?: string | null): string {
46	  if (!email) return "User";
47	  const name = email.split("@")[0];
48	  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
49	}
